import { test, expect } from '@playwright/test';

test.describe('Jump to Specific Page using Page Number Input', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list');
  });

  test('should successfully jump to a specific page when page number is entered', async ({ page }) => {
    // Verify initial page is displayed
    const pageIndicator = page.getByRole('status', { name: /page 1 of 10/i });
    await expect(pageIndicator).toBeVisible();

    // Locate and fill page number input using getByLabel
    const pageInput = page.getByLabel('Page Number');
    await pageInput.fill('5');

    // Locate and click jump button using getByRole
    const jumpButton = page.getByRole('button', { name: /jump/i });
    await jumpButton.click();

    // Wait for page to load
    await page.waitForResponse(response => 
      response.url().includes('/api/list') && response.status() === 200
    );

    // Verify page indicator updated to page 5
    const updatedPageIndicator = page.getByRole('status', { name: /page 5 of 10/i });
    await expect(updatedPageIndicator).toBeVisible();

    // Verify list items are displayed
    const listItems = page.getByRole('listitem');
    await expect(listItems).toHaveCount(20);

    // Verify current page button is active
    const currentPageButton = page.getByRole('button', { name: '5' });
    await expect(currentPageButton).toBeDisabled();
  });

  test('should handle invalid page number input gracefully', async ({ page }) => {
    // Locate and fill page number input with invalid value
    const pageInput = page.getByLabel('Page Number');
    await pageInput.fill('abc');

    // Locate and click jump button using getByRole
    const jumpButton = page.getByRole('button', { name: /jump/i });
    await jumpButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Please enter a valid page number');
    await expect(errorMessage).toBeVisible();

    // Verify page indicator remains on page 1
    const pageIndicator = page.getByRole('status', { name: /page 1 of 10/i });
    await expect(pageIndicator).toBeVisible();

    // Verify list items are still displayed
    const listItems = page.getByRole('listitem');
    await expect(listItems).toHaveCount(20);

    // Clear input and verify error message disappears
    await pageInput.clear();
    await expect(errorMessage).not.toBeVisible();
  });
});
